// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.entityimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.Indeximport androidx.room.PrimaryKey/** * NOUS — Episodic memory entity (Table 1). * * Specific events with time, place, context. Decays over time (Ebbinghaus) * unless reinforced. Embeddings stored separately in [MemoryEmbeddingEntity] * to avoid OOM on bulk SELECT. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "episodic_memories",    indices = [        Index("timestamp"),        Index("importance"),        Index("session_id"),        Index("is_hot"),        Index("is_deleted"),        Index("embedding_status"),    ],)data class EpisodicMemoryEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "content")    val content: String,    @ColumnInfo(name = "summary")    val summary: String? = null,    @ColumnInfo(name = "timestamp")    val timestamp: Long,  // epoch millis    @ColumnInfo(name = "importance")    val importance: Float = 0.5f,    @ColumnInfo(name = "initial_importance")    val initialImportance: Float = 0.5f,    @ColumnInfo(name = "last_accessed")    val lastAccessed: Long,    @ColumnInfo(name = "last_reinforced")    val lastReinforced: Long,    @ColumnInfo(name = "decay_constant_days")    val decayConstantDays: Float = 7.0f,    @ColumnInfo(name = "is_flashbulb")    val isFlashbulb: Boolean = false,    @ColumnInfo(name = "is_consolidated")    val isConsolidated: Boolean = false,    @ColumnInfo(name = "is_deleted")    val isDeleted: Boolean = false,  // tombstone    @ColumnInfo(name = "is_hot")    val isHot: Boolean = false,  // hot cache (last 24h)    @ColumnInfo(name = "emotional_valence")    val emotionalValence: Float? = null,  // -1.0 to 1.0    @ColumnInfo(name = "emotional_valence_pending")    val emotionalValencePending: Boolean = false,    @ColumnInfo(name = "tags")    val tags: String,  // JSON array    @ColumnInfo(name = "correlation_id")    val correlationId: String? = null,    @ColumnInfo(name = "session_id")    val sessionId: String? = null,    @ColumnInfo(name = "embedding_status")    val embeddingStatus: String = "pending",  // pending/computing/ready/failed    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,)